--
-- Struktur dari tabel `listjaringan`
--

CREATE TABLE `listjaringan` (
  `id_jaringan` varchar(10) DEFAULT NULL,
  `RO` varchar(10) DEFAULT NULL,
  `tipe_jaringan` varchar(10) DEFAULT NULL,
  `segmen` varchar(114) DEFAULT NULL,
  `jartatup_jartaplok` varchar(10) DEFAULT NULL,
  `mainlink_backuplink` varchar(10) DEFAULT NULL,
  `panjang` varchar(10) DEFAULT NULL,
  `panjang_drawing` varchar(10) DEFAULT NULL,
  `jumlah_core` varchar(10) DEFAULT NULL,
  `jenis_kabel` varchar(23) DEFAULT NULL,
  `tipe_kabel` varchar(14) DEFAULT NULL,
  `status` varchar(5) DEFAULT NULL,
  `keterangan` varchar(75) DEFAULT NULL,
  `keterangan2` varchar(27) DEFAULT NULL,
  `kode_site_insan` varchar(10) DEFAULT NULL,
  `DCI-EQX` varchar(26) DEFAULT NULL,
  `update` varchar(27) DEFAULT NULL,
  `route` varchar(10) DEFAULT NULL,
  `travelling_time` varchar(10) DEFAULT NULL,
  `verification_time` varchar(10) DEFAULT NULL,
  `restoration_time` varchar(10) DEFAULT NULL,
  `total_corrective_time` varchar(10) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci;

